return {
    Version = "2026-10-28",
    Title = "CONSOLE + COMBAT FIXES",
    Notes = {
        {
            Head = "Combat",
            Lines = { "Shotgun and the Dempsey Roll's roll: you can now walk forwards slowly (20% speed) - the same on PC, console and mobile", "Cross Counter only counters normal jabs and straights - not techniques", "Flicker jabs can knock someone down at 0 health (plain jabs still only stumble them)", "Technique hit effects play in full again (they could cut off part-way)" }
        },
        {
            Head = "Controls",
            Lines = { "PC blocking: F = body block, G = head block, and holding right click while blocking raises the guard to the head", "Right feint: tap right click while blocking, or turn on Settings > Controls > Right feint on its own key (V by default)" }
        },
        {
            Head = "Console",
            Lines = { "Ranked screen: the D-pad picks REGIONS, CUSTOM SERVER and every other button - you can choose your match regions now", "Gloves off, D-pad up picks on-screen buttons (tutorial Skip, the ranked queue chip...) - A presses, B stops", "Tutorial: X / Y pick your dash", "Pop-ups (Buy Tokens, confirm boxes, the ring doctor) pick their own buttons when they open", "Slot screen: B goes back to the title" }
        },
        {
            Head = "Mobile",
            Lines = { "Half Guard: new FEINT button - while blocking it throws a right-hand feint (BLOCK + R stays the parry)", "Knocked down: the left get-up button is back in the bottom-left corner", "Lock-on: the camera no longer zooms in and out on its own" }
        },
        {
            Head = "Fixes",
            Lines = { "PC: the E / R technique bars no longer get stuck in the top right", "The cracked rib injury sound plays now", "Nearby lights only is off by default (turn it on in Settings > Graphics for more frames)" }
        },
        {
            Head = "Oct 27: New",
            Lines = { "Walkout robes remade: a proper satin robe with white trim, a gold sash and sleeves, your name on the back", "Corkscrew Blow effects are white now" }
        },
        {
            Head = "Oct 27: Combat",
            Lines = { "Weaves dodge hooks and uppercuts whichever way you weave - even against a locked-on opponent (timing still matters)", "Jabs push your opponent back 15% less" }
        },
        {
            Head = "Oct 27: Fixes",
            Lines = { "Console: the ATM opens with B and you can move round it with the D-pad", "Console: on Statistics, pick a stat row or press L1 / R1 to see its points", "Holding Shift now starts your run as soon as you're able to (after a stun, putting gloves away...)", "Fixed walking on the spot after stopping", "Mobile: cleaner screens - bigger menus and shops, character creator, settings list, ranked regions" }
        },
        {
            Head = "Oct 27: Damage",
            Lines = { "Big damage stacks now soft-cap: stats, stances, passives and counters can't snowball past x2.2", "Counter bonuses add up instead of multiplying, capped at x1.8 (was x3)", "Interrupt counters x1.5 (was x2), whiff counters x1.4, perfect-dodge counters x1.3", "Full-Body Uppercut: 18 damage, no more leg / crouch scaling, no Chin Shatter on it", "Crouching Style uppercuts +15% (was +30%), Chin Shatter x1.25, Slip Counter toned down", "Leg Strength: +3% hook / uppercut damage per point (was +5%)" }
        },
        {
            Head = "Oct 27: Punches",
            Lines = { "Jabs and straights a little slower; hooks and uppercuts slower; body hooks 9 damage", "Philly Shell and Outboxer jabs / straights hit a little softer; Outboxer jabs stun less", "Orthodox can use Drive-By Jab" }
        },
        {
            Head = "Oct 27: Defence",
            Lines = { "Mobile: new HEAD block button. Controller: A blocks, A + RB head blocks", "Weaves: spamming them slows them down, holding one too long only grazes, tighter perfect dodge", "Feint, then dash forward to cancel the feint into a dash" }
        },
        {
            Head = "Oct 27: Footwork",
            Lines = { "More Footwork = longer dashes and shorter stuns", "Low Footwork = body hooks are more likely to take your legs" }
        },
        {
            Head = "Oct 27: Techniques",
            Lines = { "Dempsey Roll: once the hooks start landing you can't escape them", "Swing Counter now does real damage", "Liver Blow: more damage and a longer stun. Overhand Right: more damage" }
        },
        {
            Head = "Oct 27: Ranked and progress",
            Lines = { "Pick your ranked regions (EU, Asia, South NA, North NA) on the ranked screen", "Knockdowns stack across every round of a bout - each one is harder to get up from", "Losing a sparring bout gives half the win's Willpower", "Free ring doctor after 40 sparring wins (serious injuries still cost)", "Hard roadwork trains Drain Resistance" }
        },
        {
            Head = "Oct 27: Other",
            Lines = { "Mobile: look around with a second finger while moving", "Lock-on lets you zoom further out", "Boxing card shows your weight in KG and LBS", "Tap the injury reminder for each injury's details and price" }
        }
    }
}


