-- https://lua.expert

local CollectionService = game:GetService("CollectionService")

while true do
    task.wait(1)

    for _, v1 in CollectionService:GetTagged("MapSeat") do
        local SeatHome = v1:GetAttribute("SeatHome")

        if typeof(SeatHome) == "CFrame" and v1:IsA("BasePart") and not v1.Occupant and ((v1.Position - SeatHome.Position).Magnitude > 0.05 or v1.CFrame.LookVector:Dot(SeatHome.LookVector) < 0.9995) then
            v1.CFrame = SeatHome
        end
    end
end


